<!doctype html>
<html><head><meta charset="utf-8"><title>{{ $invoice->invoice_number }}</title><style>body{font-family:Arial;margin:35px;font-size:12px}h1{margin:0}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{border:1px solid #555;padding:7px;text-align:left}.right{text-align:right}.noborder td{border:0;padding:2px}@media print{@page{size:A4 portrait;margin:15mm}button{display:none}}</style></head><body>
