<table><tr><th>No</th><th>Description</th><th>Area / Luas</th><th>Qty</th><th>Unit Price</th><th>Discount</th><th>Subtotal</th></tr>@foreach($invoice->items as $item)<tr><td>{{ $loop->iteration }}</td><td>{{ $item->treatment_name }} - {{ $item->product_name }} {{ $item->variant_name }}</td><td>{{ $item->area }} @if(optional($invoice->order)->order_type === 'BUILDING')(Luas: {{ $item->total_luas }} m²)@elseif($item->panjang)({{ $item->panjang }} × {{ $item->lebar }} m; {{ $item->total_luas }} m²)@endif</td><td>{{ $item->quantity }} {{ $item->unit }}</td><td class="right">Rp {{ number_format($item->unit_price,2,',','.') }}</td><td class="right">Rp {{ number_format($item->discount,2,',','.') }}</td><td class="right">Rp {{ number_format($item->subtotal,2,',','.') }}</td></tr>@endforeach</table>
<table class="noborder" style="margin-left:auto;width:40%"><tr><td>Subtotal</td><td class="right">Rp {{ number_format($invoice->subtotal,2,',','.') }}</td></tr><tr><td>Discount</td><td class="right">Rp {{ number_format($invoice->discount,2,',','.') }}</td></tr><tr><td>Tax</td><td class="right">Rp {{ number_format($invoice->tax_amount,2,',','.') }}</td></tr><tr><td><b>Grand Total</b></td><td class="right"><b>Rp {{ number_format($invoice->grand_total,2,',','.') }}</b></td></tr><tr><td>Outstanding</td><td class="right">Rp {{ number_format($invoice->outstanding_amount,2,',','.') }}</td></tr></table>
